<template><el-button v-if="canQuery" :disabled="disabled" @click="open">模板对照预览</el-button><el-dialog v-model="visible" title="双模板对照 · 不保存、不发布" width="96%" append-to-body :close-on-click-modal="false" destroy-on-close @closed="clear"><el-alert title="左侧为已保存外观草稿，右侧为候选模板。同一份公开内容，不包含未保存的表单修改；样式按各自模板展示。" :closable="false"/><el-form inline style="margin-top:12px"><el-form-item label="候选模板"><el-select :disabled="busy" v-model="target" style="width:170px"><el-option v-for="t in themes" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item><el-form-item label="栏目ID（0首页）"><el-input-number :disabled="busy" v-model="channelId" :min="0" :precision="0" controls-position="right"/></el-form-item><el-form-item label="候选栏目布局"><el-select :empty-values="[null,undefined]" v-model="layout" :disabled="busy||!channelId" style="width:155px"><el-option label="沿用保存设置" value=""/><el-option label="网格" value="grid"/><el-option label="列表" value="list"/></el-select></el-form-item><el-button :loading="busy" @click="compare">生成对照</el-button></el-form><p v-for="s in differences" :key="s" class="difference">{{s}}</p><div class="comparison"><section><h3>已保存草稿</h3><iframe v-if="left" :srcdoc="left" title="已保存模板预览" sandbox="" referrerpolicy="no-referrer"/></section><section><h3>候选模板</h3><iframe v-if="right" :srcdoc="right" title="候选模板预览" sandbox="" referrerpolicy="no-referrer"/></section></div><template #footer><el-button @click="visible=false">关闭</el-button></template></el-dialog></template>
<script setup>
import{ref,onBeforeUnmount,onDeactivated,computed,watch}from'vue';import request from'@/utils/request';import auth from'@/plugins/auth';import{privateImage}from'@/api/cms/content';const props=defineProps({version:Number,suggestedTheme:String,themes:{type:Array,default:()=>[]},disabled:Boolean}),visible=ref(false),left=ref(''),right=ref(''),busy=ref(false),target=ref('industrial'),channelId=ref(0),layout=ref(''),differences=ref([]),canQuery=computed(()=>auth.hasPermi('cms:site:query'));let epoch=0;const urls=[];function clear(){++epoch;for(const u of urls)URL.revokeObjectURL(u);urls.length=0;left.value='';right.value='';differences.value=[];busy.value=false}function close(){visible.value=false;clear()}function open(){clear();target.value=props.suggestedTheme||'industrial';channelId.value=0;layout.value='';visible.value=true}async function prepare(html,n){if(n!==epoch)return ''; const doc=new DOMParser().parseFromString(html,'text/html');for(const img of doc.querySelectorAll('img')){const m=/^\/media\/([1-9][0-9]*)$/.exec(img.getAttribute('src')||'');if(!m||!auth.hasPermi('cms:asset:query')){img.remove();continue}try{const blob=await privateImage(Number(m[1]));if(n!==epoch)return '';const u=URL.createObjectURL(blob);urls.push(u);img.src=u}catch{img.remove()}}for(const link of doc.querySelectorAll('link[rel="stylesheet"]'))link.href=new URL(link.getAttribute('href'),location.origin).href;for(const a of doc.querySelectorAll('a'))a.removeAttribute('href');for(const f of doc.querySelectorAll('form'))f.removeAttribute('action');const csp=doc.createElement('meta');csp.httpEquiv='Content-Security-Policy';csp.content="default-src 'none'; img-src blob:; style-src 'unsafe-inline' "+location.origin+"; base-uri 'none'; form-action 'none'";doc.head.prepend(csp);return '<!doctype html>'+doc.documentElement.outerHTML}async function compare(){if(busy.value)return;clear();const n=epoch;busy.value=true;try{const r=await request({url:'/cms/site/compare',method:'post',data:{version:props.version,theme:target.value,channelId:channelId.value,layout:channelId.value?layout.value:''},timeout:60000});if(n!==epoch||!visible.value)return;const a=await prepare(r.data.beforeHtml,n),b=await prepare(r.data.afterHtml,n);if(n!==epoch||!visible.value)return;left.value=a;right.value=b;differences.value=[r.data.scope,...r.data.differences]}finally{if(n===epoch)busy.value=false}}watch([target,channelId,layout],clear);onBeforeUnmount(close);onDeactivated(close)
</script><style scoped>.comparison{display:grid;grid-template-columns:1fr 1fr;gap:16px}.comparison section{min-width:0}.comparison h3{font-size:14px}.comparison iframe{border:1px solid #ddd;width:100%;height:62vh}.difference{font-size:13px;margin:6px 0;color:#667}@media(max-width:900px){.comparison{grid-template-columns:1fr}}</style>
